def seed_all():
    """Создать недостающие статьи из SEED_DOCS."""
    try:
        doc_db.ensure_tables()
    except Exception as e:
        print(f"[Documentation] seed: cannot ensure tables: {e}")
        return

    for doc in SEED_DOCS:
        try:
            if doc_db.get_doc_by_slug(doc["slug"]):
                continue
            doc_db.upsert_doc(
                slug=doc["slug"],
                section=doc["section"],
                title=doc["title"],
                content=doc["content"],
                sort_order=doc.get("sort", 0),
                user="system",
            )
            print(f"[Documentation] seed: created {doc['slug']}")
        except Exception as e:
            print(f"[Documentation] seed error for {doc['slug']}: {e}")